import React, { useState, useEffect } from "react";
import styled from "styled-components";
import axios from "axios";

const PageContainer = styled.div`
  font-family: Arial, sans-serif;
  display: flex;
  flex-direction: column;
  background-color: #f9f9f9;
  height: 100vh;
  padding: 20px;
`;

const HeaderBar = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  font-size: 18px;
`;

const Content = styled.div`
  display: flex;
  margin-top: 20px;
  gap: 20px;
`;

const Sidebar = styled.aside`
  width: 200px;
  background-color: #ffffff;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  padding: 20px;
`;

const SidebarItem = styled.div`
  padding: 10px;
  margin-bottom: 10px;
  border-radius: 5px;
  cursor: pointer;
  background-color: ${(props) => (props.active ? "#007bff" : "#f1f1f1")};
  color: ${(props) => (props.active ? "white" : "black")};
  &:hover {
    background-color: #007bff;
    color: white;
  }
`;

const EmployeeList = styled.div`
  width: 300px;
  padding: 10px;
  background-color: white;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
`;

const EmployeeItem = styled.div`
  padding: 10px;
  border-bottom: 1px solid #f1f1f1;
  cursor: pointer;
  &:hover {
    background-color: #f1f1f1;
  }
`;

const EmployeeInfo = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 20px;
`;

const Card = styled.div`
  background-color: white;
  border-radius: 5px;
  padding: 20px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
`;

const Row = styled.div`
  display: flex;
  gap: 20px;
`;

const AddButton = styled.button`
  margin-top: 20px;
  width: 100%;
  padding: 10px;
  background-color: #28a745;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-weight: bold;
  &:hover {
    background-color: #218838;
  }
`;

const EmployeePage = () => {
  const [selectedRole, setSelectedRole] = useState("driver");
  const [employees, setEmployees] = useState([]);
  const [selectedEmployee, setSelectedEmployee] = useState(null);

  useEffect(() => {
    fetchEmployees();
  }, [selectedRole]);

  const fetchEmployees = async () => {
    try {
      const response = await axios.get(`/api/employees?role=${selectedRole}`);
      setEmployees(response.data);
      setSelectedEmployee(null);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  const handleAddEmployee = () => {
    // Logic for adding a new employee
  };

  return (
    <PageContainer>
      <HeaderBar>
        <div>Employee Management</div>
      </HeaderBar>

      <Content>
        <Sidebar>
          {["driver", "driller", "manager", "worker"].map((role) => (
            <SidebarItem
              key={role}
              active={selectedRole === role}
              onClick={() => setSelectedRole(role)}
            >
              {role.charAt(0).toUpperCase() + role.slice(1)}
            </SidebarItem>
          ))}
          <AddButton onClick={handleAddEmployee}>Add Employee</AddButton>
        </Sidebar>

        <EmployeeList>
          {employees.map((employee) => (
            <EmployeeItem
              key={employee.id}
              onClick={() => setSelectedEmployee(employee)}
            >
              {employee.name}
            </EmployeeItem>
          ))}
        </EmployeeList>

        {selectedEmployee && (
          <EmployeeInfo>
            <Row>
              <Card>
                <h3>Name</h3>
                <p>{selectedEmployee.name}</p>
              </Card>
              <Card>
                <h3>Phone</h3>
                <p>{selectedEmployee.phone}</p>
              </Card>
              <Card>
                <h3>Fixed Salary</h3>
                <p>{selectedEmployee.fixed_salary}</p>
              </Card>
            </Row>
            <Row>
              <Card>
                <h3>Expense</h3>
                <p>{selectedEmployee.expense}</p>
              </Card>
              <Card>
                <h3>Earned Money</h3>
                <p>{selectedEmployee.earned_money}</p>
              </Card>
              <Card>
                <h3>Remaining Amount</h3>
                <p>{selectedEmployee.remaining_amount}</p>
              </Card>
            </Row>
            <Row>
              <Card>
                <h3>Days Worked</h3>
                <p>{selectedEmployee.days_worked}</p>
              </Card>
            </Row>
          </EmployeeInfo>
        )}
      </Content>
    </PageContainer>
  );
};

export default EmployeePage;
